// index.ts
import {
  createRuntime,
  createRequest,
  getBuiltinModel,
  adaptAiModel,
  createStreamFnFromAi,
} from "aipack";

async function main() {
  // 1. 选择模型 + 从环境变量读取 Key
  const aiModel = getBuiltinModel("deepseek", "deepseek-chat");

  // 2. 创建 Runtime（Agent 核心调度器）
  const runtime = createRuntime({
    model: adaptAiModel(aiModel),
    streamFn: createStreamFnFromAi(aiModel),
    systemPrompt: "你是一个友好、简洁的 AI 助手，回答尽量精炼。",
  });

  // 3. 发起请求
  const result = await runtime.run(
    createRequest("你好！请用一句话介绍你自己。")
  );

  console.log("\n🤖 助手:", result.content);
  console.log("\n✅ 成功标志:", result.success);
  console.log("📊 Token 输入用量:", result.usage.input);

  await runtime.close();
}

main().catch(console.error);

