import {
  createRuntime,
  createRequest,
  getBuiltinModel,
  adaptAiModel,
  createStreamFnFromAi,
} from "aipack";

const runtime = createRuntime({
  model: adaptAiModel(getBuiltinModel("deepseek", "deepseek-chat")),
  streamFn: createStreamFnFromAi(getBuiltinModel("deepseek", "deepseek-chat")),
});

async function streamingDemo() {
  process.stdout.write("\n🤖 助手: ");

  // stream() 返回异步生成器，逐块产出增量
  for await (const chunk of runtime.stream(
    createRequest("写一首关于秋天的短诗，四言绝句即可。")
  )) {
    switch (chunk.type) {
      case "text":
        // 文本增量：直接写出，实现打字机效果
        process.stdout.write(chunk.content ?? "");
        break;
      case "thinking_delta":
        // 推理模型的思考过程增量（可选展示）
        // process.stdout.write(chunk.content ?? "");
        break;
      case "tool_start":
        console.log(`\n\n[工具开始] ${chunk.toolName}`);
        break;
      case "tool_end":
        console.log(`\n[工具结束] ${chunk.toolName}`);
        break;
      case "done":
        console.log("\n\n——— 生成结束 ———");
        break;
      case "error":
        console.error("\n错误:", chunk.error);
        break;
    }
  }
  await runtime.close();
}

streamingDemo();

qsMultiTurnCode:
import {
  createRuntime,
  createRequest,
  createFileSessionStorage,
  getBuiltinModel,
  adaptAiModel,
  createStreamFnFromAi,
} from "aipack";

const aiModel = getBuiltinModel("deepseek", "deepseek-chat");

const runtime = createRuntime({
  model: adaptAiModel(aiModel),
  streamFn: createStreamFnFromAi(aiModel),
  // 开启文件持久化（maxAge 单位：毫秒。30 天如下）
  sessionStorage: createFileSessionStorage({
    baseDir: "./sessions",
    maxAge: 30 * 24 * 60 * 60 * 1000,
  }),
});

async function multiTurn() {
  const sessionKey = "user-001";

  // === 第一轮：设定信息 ===
  await runtime.run(createRequest("记住：我叫张三，在北京工作，喜欢听音乐。", {
    sessionKey,
  }));

  // === 第二轮：查询 ===
  // 因为使用相同 sessionKey，历史消息会被自动恢复
  const r2 = await runtime.run(createRequest("我叫什么？我在哪工作？我的爱好是？", {
    sessionKey,
  }));
  console.log("🤖:", r2.content);
  // 预期输出会包含：张三、北京、听音乐

  // 查看会话列表
  const sessions = await runtime.listSessions();
  console.log("\n会话列表:", sessions);

  await runtime.close();
}

multiTurn();

